// Bitmap fonts: fixed width, one byte per glyph row (leftmost pixel in bit
// 7), character codes 0 to 255 (Latin-1).
#pragma once

#include <cstdint>

namespace gfx {

struct Font {
    uint8_t width;
    uint8_t height;
    const uint8_t *glyphs; // 256 glyphs of `height` bytes each

    const uint8_t *glyph(uint8_t code) const { return glyphs + code * height; }
};

// Spleen 6x12, the interface font. Generated by tools/gen_font.py.
extern const Font kSpleen6x12;

// A larger font with only some characters, (width + 7) / 8 bytes per row,
// leftmost pixel in the top bit of each row's first byte.
struct WideFont {
    uint8_t width;
    uint8_t height;
    uint8_t bytes_per_row;
    const char *chars; // the characters it has, in order
    const uint8_t *glyphs;

    // nullptr when the font lacks the character.
    const uint8_t *glyph(char c) const
    {
        for (int i = 0; chars[i] != 0; i++) {
            if (chars[i] == c) {
                return glyphs + i * height * bytes_per_row;
            }
        }
        return nullptr;
    }
};

// The self-test screen: Spleen 8x16, printable ASCII.
extern const WideFont kSpleen8x16;

// Reads the next character of a UTF-8 string as a Latin-1 code, and moves
// `text` past it. Characters outside Latin-1 come back as '?'. Returns 0 at
// the end of the string.
uint8_t next_latin1(const char *&text);

} // namespace gfx
